'use client';

import React, { useState, useRef } from 'react';
import { Mail, Lock, User, ArrowRight, X, CheckCircle2 } from 'lucide-react';
import ReCAPTCHA from 'react-google-recaptcha';
import './AuthModal.css';

export interface UserData {
  name: string;
  email: string;
}

interface AuthModalProps {
  isOpen: boolean;
  onClose: () => void;
  onLoginSuccess?: (userData: UserData) => void;
}

// قائمة النطاقات المسموح بها من الشركات العالمية
const ALLOWED_DOMAINS = [
  'gmail.com',
  'yahoo.com',
  'outlook.com',
  'hotmail.com',
  'icloud.com',
  'live.com',
  'protonmail.com',
];

export default function AuthModal({ isOpen, onClose, onLoginSuccess }: AuthModalProps) {
  const [isSignUp, setIsSignUp] = useState<boolean>(false);

  // Form States
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');

  // CAPTCHA State & Ref
  const [captchaToken, setCaptchaToken] = useState<string | null>(null);
  const recaptchaRef = useRef<ReCAPTCHA>(null);

  if (!isOpen) return null;

  // دالة التحقق من مزود البريد الإلكتروني
  const isAllowedEmail = (emailStr: string): boolean => {
    const domain = emailStr.split('@')[1]?.toLowerCase();
    return ALLOWED_DOMAINS.includes(domain);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // 1. التحقق من المزود المسموح للبريد
    if (!isAllowedEmail(email)) {
      alert(`Please use a valid email address from global providers: (${ALLOWED_DOMAINS.slice(0, 5).join(', ')}, etc.)`);
      return;
    }

    // 2. التحقق من إكمال الكابتشا
    if (!captchaToken) {
      alert('Please complete the "I am not a robot" verification.');
      return;
    }

    if (isSignUp) {
      if (password !== confirmPassword) {
        alert('Passwords do not match!');
        return;
      }
    }

    // تجهيز بيانات المستخدم للنقل
    const userData: UserData = {
      name: isSignUp ? fullName : (fullName || email.split('@')[0]),
      email: email,
    };

    if (onLoginSuccess) {
      onLoginSuccess(userData);
    }
    onClose();
  };

  const handleCaptchaChange = (token: string | null) => {
    setCaptchaToken(token);
  };

  return (
    <div className="auth-overlay" onClick={onClose}>
      <div className="auth-modal-card" onClick={(e) => e.stopPropagation()}>
        
        {/* Close Button */}
        <button className="modal-close-btn" onClick={onClose} aria-label="Close modal">
          <X size={20} />
        </button>

        {/* Modal Header */}
        <div className="auth-header">
          <h2>{isSignUp ? 'Create Account' : 'Welcome Back'}</h2>
          <p>
            {isSignUp
              ? 'Join OBSIDIAN-X for exclusive access & order tracking'
              : 'Sign in to access your saved items and account settings'}
          </p>
        </div>

        {/* Switcher Tabs */}
        <div className="auth-tabs">
          <button
            className={`tab-btn ${!isSignUp ? 'active' : ''}`}
            onClick={() => {
              setIsSignUp(false);
              setCaptchaToken(null);
              recaptchaRef.current?.reset();
            }}
          >
            Sign In
          </button>
          <button
            className={`tab-btn ${isSignUp ? 'active' : ''}`}
            onClick={() => {
              setIsSignUp(true);
              setCaptchaToken(null);
              recaptchaRef.current?.reset();
            }}
          >
            Register
          </button>
        </div>

        {/* Form Content */}
        <form onSubmit={handleSubmit} className="auth-form">
          {isSignUp && (
            <div className="input-group">
              <label>Full Name</label>
              <div className="input-icon-wrapper">
                <User className="field-icon" size={18} />
                <input
                  type="text"
                  placeholder="John Doe"
                  value={fullName}
                  onChange={(e) => setFullName(e.target.value)}
                  required
                />
              </div>
            </div>
          )}

          <div className="input-group">
            <label>Email Address</label>
            <div className="input-icon-wrapper">
              <Mail className="field-icon" size={18} />
              <input
                type="email"
                placeholder="name@gmail.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>
          </div>

          <div className="input-group">
            <label>Password</label>
            <div className="input-icon-wrapper">
              <Lock className="field-icon" size={18} />
              <input
                type="password"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </div>
          </div>

          {isSignUp && (
            <div className="input-group">
              <label>Confirm Password</label>
              <div className="input-icon-wrapper">
                <Lock className="field-icon" size={18} />
                <input
                  type="password"
                  placeholder="••••••••"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  required
                />
              </div>
            </div>
          )}

          {!isSignUp && (
            <div className="forgot-password-row">
              <a href="#">Forgot password?</a>
            </div>
          )}

          {/* reCAPTCHA Component */}
          <div className="recaptcha-wrapper" style={{ margin: '16px 0', display: 'flex', justifyContent: 'center' }}>
            <ReCAPTCHA
              ref={recaptchaRef}
              sitekey="6LePobktAAAAAF9vjRtvArRYu5Tuwzq3ay6UH6P-"
              onChange={handleCaptchaChange}
            />
          </div>

          <button type="submit" className="submit-btn" disabled={!captchaToken}>
            <span>{isSignUp ? 'Create Account' : 'Sign In'}</span>
            <ArrowRight size={18} />
          </button>
        </form>

        {/* Bottom Feature Badges */}
        <div className="auth-features">
          <div className="feature-item">
            <CheckCircle2 size={16} />
            <span>Fast Express Delivery</span>
          </div>
          <div className="feature-item">
            <CheckCircle2 size={16} />
            <span>100% Secure Checkout</span>
          </div>
        </div>

      </div>
    </div>
  );
}